#include <vector>
#include <stdexcept>
#include <cmath>
#include <cassert>
#include <iostream>
double weighted_mean(const std::vector<double>& values, const std::vector<double>& weights) {
    if(values.empty() || values.size()!=weights.size()) throw std::invalid_argument("sizes");
    double total=0, sum=0;
    for(size_t i=0;i<values.size();++i){if(weights[i]<0)throw std::invalid_argument("weight");total+=weights[i];sum+=values[i]*weights[i];}
    if(total<=0)throw std::invalid_argument("zero total");return sum/total;
}
